321	
322	    SCB_InvalidateDCache_by_Addr((void *)hflash->base, nand_pagesize + SPI_NAND_MAXOOB_SIZE);
323	    if (((blk & 1) != 0) && (hflash->wakeup != 0))
324	        SCB_InvalidateDCache_by_Addr((void *)(hflash->base + (1 << 12)), SPI_NAND_PAGE_SIZE + SPI_NAND_MAXOOB_SIZE);
325	    int bad = HAL_NAND_GET_BADBLK(hflash, blk);
326	
327	    return bad;
328	}
