746	#ifdef CODE_IN_RAM
747	    boot_mpu_img((uint8_t *)(HPSYS_RAM0_BASE + 0x20000));
748	#endif
749	
750	    /* set MPI1 clock divider for PSRAM */
751	    BSP_SetFlash1DIV(1);
752	    BSP_SetFlash2DIV(1);
753	
754	    HAL_HPAON_EnableXT48();
