756	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_HXT48);
757	    // HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_HP_PERI, RCC_CLK_PERI_HXT48);
758	    boot_uart_init();
759	
760	    HAL_PMU_EnableDLL(1);
761	
762	    dwtIpInit();
763	    /* wait until 2ms elapse to ensure flash LDO is stable before flash access
764	     * default clock is 24MHz, maybe slower than 24MHz at startup stage
765	     *
766	     */
767	    while (dwtGetCycles() < (2 * 24000))
768	    {
769	    }
770	
771	    HAL_RCC_HCPU_EnableDLL1(240000000);
772	    /* set hdiv again to make HCLK run on 240MHz actually
773	     * Although the default hdiv registe value is 1, hardware would use 2 as the
774	     * default hdiv. After write the hdiv register, hardware would use the
775	     * updated value.
776	     */
777	    HAL_RCC_HCPU_SetDiv(1, 2, 5);
778	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_DLL1);
779	
780	    __HAL_SYSCFG_HPBG_EN();
781	    __HAL_SYSCFG_HPBG_VDDPSW_EN();
782	
783	    dwtIpInit();
784	    /* wait until 2ms elapse to ensure flash LDO is stable before flash access
785	     * default clock is 24MHz, maybe slower than 24MHz at startup stage
786	     *
787	     */
788	    while (dwtGetCycles() < (20 * 2400))
789	    {
790	    }
791	
792	    if (CHIP_IS_583() || CHIP_IS_585())
793	    {
794	        HAL_RCC_HCPU_EnableDLL2(240000000);
795	    }
796	    else if (CHIP_IS_587())
797	    {
798	        HAL_RCC_HCPU_EnableDLL2(336000000);
799	        HAL_RCC_HCPU_EnableDLL3(216000000);
800	        HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH4, RCC_CLK_FLASH_DLL3);
801	    }
802	
803	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH1, RCC_CLK_FLASH_DLL2);
804	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH2, RCC_CLK_FLASH_DLL2);
805	
806	    HAL_Delay_us(0);
807	}
