822	static uint8_t sd_cache[512];
823	static uint32_t sdmmc_mem_base;
824	
825	static int read_sd_emmc(uint32_t addr, const int8_t *buf, uint32_t size)
826	{
827	    HAL_ASSERT(sdmmc_mem_base);
828	
829	    uint32_t offset = addr - sdmmc_mem_base;
830	    uint32_t remain = size;
831	    uint8_t *data = (uint8_t *)buf;
832	
833	    while (remain >= 512)
834	    {
835	        sd_read_data(offset, data, 512);
836	        remain -= 512;
837	        offset += 512;
838	        data += 512;
839	    }
840	    if (remain > 0)
841	    {
842	        sd_read_data(offset, sd_cache, 512);
843	        memcpy(data, sd_cache, remain);
844	    }
845	    return size;
846	}
