941	void boot_images_help(void)
942	{
943	    dfu_install_info info;
944	    dfu_install_info info_ext;
945	    if (dfu_flash_reader != NULL)
946	    {
947	        if (DFU_DOWNLOAD_REGION_START_ADDR != FLASH_UNINIT_32)
948	        {
949	            dfu_flash_reader(DFU_DOWNLOAD_REGION_START_ADDR, (const int8_t *)&info, sizeof(dfu_install_info));
950	        }
951	        if (DFU_INFO_REGION_START_ADDR != FLASH_UNINIT_32)
952	        {
953	            dfu_flash_reader(DFU_INFO_REGION_START_ADDR, (const int8_t *)&info_ext, sizeof(dfu_install_info));
954	        }
955	        if (info.magic == SEC_CONFIG_MAGIC && info_ext.magic == SEC_CONFIG_MAGIC)
956	        {
957	            info = info_ext;
958	        }
959	    }
960	
961	    g_sec_config = (struct sec_configuration *)FLASH_BASE_ADDR;
962	
963	    read_nor(FLASH_BASE_ADDR, (const int8_t *)&sec_config_cache, sizeof(struct sec_configuration));
964	
965	    select_boot();
966	
967	    if (DFU_DOWNLOAD_REGION_START_ADDR != FLASH_UNINIT_32)
968	    {
969	        if ((HAL_Get_backup(RTC_BAKCUP_OTA_FORCE_MODE) == DFU_FORCE_MODE_REBOOT_TO_PACKAGE_OTA_MANAGER) ||
970	                (info.magic == SEC_CONFIG_MAGIC) && (info.install_state == DFU_PACKAGE_INSTALL))
971	        {
972	            sec_config_cache.running_imgs[CORE_HCPU] = (struct image_header_enc *) & (((struct sec_configuration *)FLASH_TABLE_START_ADDR)->imgs[DFU_FLASH_IMG_IDX(DFU_FLASH_IMG_LCPU)]);
973	        }
974	    }
975	
976	    if (g_sec_config->magic == SEC_CONFIG_MAGIC)
977	    {
978	        if (g_sec_config->running_imgs[CORE_BOOT] != (struct image_header_enc *)FLASH_UNINIT_32)
979	        {
980	            int flash_id = g_sec_config->running_imgs[CORE_BOOT] - &(g_sec_config->imgs[0]) + DFU_FLASH_IMG_LCPU;
981	            dfu_boot_img_in_flash(flash_id);
982	        }
983	
984	        /* load extended img if present, such as ACPU img */
985	        if (g_sec_config->imgs[DFU_FLASH_IMG_IDX(DFU_FLASH_HCPU_EXT2)].length != FLASH_UNINIT_32)
986	        {
987	            dfu_boot_img_in_flash(DFU_FLASH_HCPU_EXT2);
988	        }
989	
990	        if (g_sec_config->running_imgs[CORE_HCPU] != (struct image_header_enc *)FLASH_UNINIT_32)
991	        {
992	            int flash_id = ((uint32_t)sec_config_cache.running_imgs[CORE_HCPU] - FLASH_BASE_ADDR - 0x1000) / sizeof(struct image_header_enc) + DFU_FLASH_IMG_LCPU;
993	            dfu_boot_img_in_flash(flash_id);
994	        }
995	
996	        boot_image(CORE_HCPU, 0);
997	    }
998	}
