    flash (rx) : ORIGIN = 0x1C020000, LENGTH = 256K
    sram (rwx) : ORIGIN = 0x20000000, LENGTH = 1536K
    retention_ram (rw) : ORIGIN = 0x00020000, LENGTH = 64K
    psram (rwx) : ORIGIN = 0x60000000, LENGTH = 32M
}
__flash_start = ORIGIN(flash);
__flash_size = LENGTH(flash);
__sram_start = ORIGIN(sram);
__sram_size = LENGTH(sram);
