/* __start must set MSP before any C code runs, because the SiFli ROM
 * bootloader does NOT load MSP from our vector table — it keeps its
 * own stack (which may be below MSPLIM, causing an immediate STKOF
 * UsageFault when start() tries to push LR).
 *
 * We use a naked prologue written entirely in assembly to:
 *   1. Load the correct initial SP from our vector table (_vectors[0])
 *   2. Clear MSPLIM (disable hardware stack limit until NuttX sets it up)
 *   3. Set VTOR to our vector table
 *   4. Disable interrupts
 *   5. Then fall through to the normal C startup
 */

void __start(void)
{
  /* clang-format off */
  __asm volatile (
      ".syntax unified\n"
      ".thumb\n"

      /* Load our vector table base address */
      "ldr  r0, =_vectors\n"

      /* Set MSP from _vectors[0] (initial stack pointer) */
      "ldr  r1, [r0, #0]\n"
      "msr  msp, r1\n"

      /* Clear MSPLIM to disable hardware stack limit checking.
       * NuttX will set this up properly later.
       */
      "movs r1, #0\n"
      "msr  msplim, r1\n"

      /* Disable interrupts */
      "cpsid i\n"

      /* Set VTOR to our vector table */
      "ldr  r1, =0xE000ED08\n"
      "str  r0, [r1, #0]\n"

      /* ISB to ensure VTOR and MSP changes take effect */
      "isb sy\n"

      /* Now safe to use C. Load __start_c address and branch. */
      "b    __start_c\n"
      ".ltorg\n"
      :
      :
      : "r0", "r1", "memory"
  );
  /* clang-format on */

  /* Never reached — the asm branches to __start_c */
  for (;;);
}

