184	static int sifli_setup(uart_dev_t *serial)
185	{
186	    struct sifli_uart *uart;
187	    uart = (struct sifli_uart *)serial->priv;
188	    struct serial_configure *cfg=&uart->ser_cfg;
189	
190	    uart->handle.Instance          = uart->config->Instance;
191	    uart->handle.Init.BaudRate     = cfg->baud_rate;
192	    uart->handle.Init.HwFlowCtl    = cfg->hwfc;
193	    uart->handle.Init.HwFlowCtl    <<= USART_CR3_RTSE_Pos;
194	    uart->handle.Init.Mode         = UART_MODE_TX_RX;
195	    uart->handle.Init.OverSampling = UART_OVERSAMPLING_16;
196	
197	    if (cfg->parity && cfg->data_bits < DATA_BITS_9)
198	        cfg->data_bits++;                           // parity is part of data
199	
200	    switch (cfg->data_bits)
201	    {
202	    case DATA_BITS_6:
203	        uart->handle.Init.WordLength = UART_WORDLENGTH_6B;
204	        break;
205	    case DATA_BITS_7:
206	        uart->handle.Init.WordLength = UART_WORDLENGTH_7B;
207	        break;
208	    case DATA_BITS_8:
209	        uart->handle.Init.WordLength = UART_WORDLENGTH_8B;
210	        break;
211	    case DATA_BITS_9:
212	        uart->handle.Init.WordLength = UART_WORDLENGTH_9B;
213	        break;
214	    default:
215	        uart->handle.Init.WordLength = UART_WORDLENGTH_8B;
216	        break;
217	    }
218	    switch (cfg->stop_bits)
219	    {
220	    case STOP_BITS_1:
221	        uart->handle.Init.StopBits   = UART_STOPBITS_1;
222	        break;
223	    case STOP_BITS_2:
224	        uart->handle.Init.StopBits   = UART_STOPBITS_2;
225	        break;
226	    case STOP_BITS_3:
227	        uart->handle.Init.StopBits   = UART_STOPBITS_0_5;
228	        break;
229	    case STOP_BITS_4:
230	        uart->handle.Init.StopBits   = UART_STOPBITS_1_5;
231	        break;
232	    default:
233	        uart->handle.Init.StopBits   = UART_STOPBITS_1;
234	        break;
235	    }
236	    switch (cfg->parity)
237	    {
238	    case PARITY_NONE:
239	        uart->handle.Init.Parity     = UART_PARITY_NONE;
240	        break;
241	    case PARITY_ODD:
242	        uart->handle.Init.Parity     = UART_PARITY_ODD;
243	        break;
244	    case PARITY_EVEN:
245	        uart->handle.Init.Parity     = UART_PARITY_EVEN;
246	        break;
247	    default:
248	        uart->handle.Init.Parity     = UART_PARITY_NONE;
249	        break;
250	    }
251	
252	    if (HAL_UART_Init(&uart->handle) != HAL_OK)
253	    {
254	        return -EINVAL;
255	    }
256	
257	    return OK;
258	}
