260	/****************************************************************************
261	 * Name: nrf53_ioctl
262	 *
263	 * Description:
264	 *   All ioctl calls will be routed through this method
265	 *
266	 ****************************************************************************/
267	
268	static int sifli_ioctl(struct file *filep, int cmd, unsigned long arg)
269	{
270	#ifdef CONFIG_SERIAL_TERMIOS
271	  struct inode         *inode  = filep->f_inode;
272	  struct uart_dev_s    *dev    = inode->i_private;
273	  struct sifli_uart    *uart = (struct sifli_uart *)dev->priv;
274	  struct serial_configure *config = &uart->ser_cfg;
275	#endif
276	  int                   ret    = OK;
277	
278	  switch (cmd)
279	    {
280	#ifdef CONFIG_SERIAL_TERMIOS
281	      case TCGETS:
282	        {
283	          struct termios *termiosp = (struct termios *)arg;
284	
285	          if (!termiosp)
286	            {
287	              ret = -EINVAL;
288	              break;
289	            }
290	
291	          termiosp->c_cflag = ((config->parity != 0) ? PARENB : 0)
292	                              | ((config->parity == 1) ? PARODD : 0)
293	                              | ((config->stop_bits==STOP_BITS_2) ? CSTOPB : 0) |
294	#ifdef CONFIG_SERIAL_OFLOWCONTROL
295	                              ((config->hwfc&RT_SERIAL_HWFC_CTS) ? CCTS_OFLOW : 0) |
296	#endif
297	#ifdef CONFIG_SERIAL_IFLOWCONTROL
298	                              ((config->hwfc&RT_SERIAL_HWFC_RTS) ? CRTS_IFLOW : 0) |
299	#endif
300	                              CS8;
301	
302	          cfsetispeed(termiosp, config->baud_rate);
303	
304	          break;
305	        }
306	
307	      case TCSETS:
308	        {
309	          struct termios *termiosp = (struct termios *)arg;
310	
311	          if (!termiosp)
312	            {
313	              ret = -EINVAL;
314	              break;
315	            }
316	
317	          /* Perform some sanity checks before accepting any changes */
318	
319	          if ((termiosp->c_cflag & CSIZE) != CS8)
320	            {
321	              ret = -EINVAL;
322	              break;
323	            }
324	
325	#ifndef HAVE_UART_STOPBITS
326	          if ((termiosp->c_cflag & CSTOPB) != 0)
327	            {
328	              ret = -EINVAL;
329	              break;
330	            }
331	#endif
332	
333	          if (termiosp->c_cflag & PARODD)
334	            {
335	              ret = -EINVAL;
336	              break;
337	            }
338	
339	          /* TODO: CCTS_OFLOW and CRTS_IFLOW */
340	
341	          /* Parity */
342	
343	          if (termiosp->c_cflag & PARENB)
344	            {
345	              config->parity = (termiosp->c_cflag & PARODD) ? 1 : 2;
346	            }
347	          else
348	            {
349	              config->parity = 0;
350	            }
351	
352	#ifdef HAVE_UART_STOPBITS
353	          /* Stop bits */
354	
355	          config->stop_bits = (termiosp->c_cflag & CSTOPB) ? STOP_BITS_2:STOP_BITS_1;
356	#endif
357	
358	          /* Note that only cfgetispeed is used because we have knowledge
359	           * that only one speed is supported.
360	           */
361	
362	          config->baud_rate = cfgetispeed(termiosp);
363	
364	          /* Effect the changes */
365	
366	          sifli_setup(dev);
367	
368	          break;
369	        }
370	#endif
371	
372	      default:
373	        {
374	          ret = -ENOTTY;
375	          break;
376	        }
377	    }
378	
379	  return ret;
380	}
