396	static void sifli_rxint(struct uart_dev_s *dev, bool enable)
397	{
398	    struct sifli_uart *uart = (struct sifli_uart *)dev->priv;
399	
400	    /* In DMA RX mode, use IDLE interrupt instead of RXNE interrupt */
401	    if (uart->uart_rx_dma_flag)
402	    {
403	        if (enable)
404	        {
405	            __HAL_UART_ENABLE_IT(&(uart->handle), UART_IT_IDLE);
406	            up_enable_irq(uart->config->irq_type+16);
407	        }
408	        else
409	        {
410	            __HAL_UART_DISABLE_IT(&(uart->handle), UART_IT_IDLE);
411	            up_disable_irq(uart->config->irq_type+16);
412	        }
413	    }
414	    else
415	    {
416	        if (enable)
417	        {
418	            /* Enable UART RXNE interrupt */
419	            __HAL_UART_ENABLE_IT(&(uart->handle), UART_IT_RXNE);
420	            up_enable_irq(uart->config->irq_type+16);
421	        }
422	        else
423	        {
424	            /* Disable UART RXNE interrupt */
425	            __HAL_UART_DISABLE_IT(&(uart->handle), UART_IT_RXNE);
426	            up_disable_irq(uart->config->irq_type+16);
427	        }
428	    }
429	}
430	
431	static int sifli_dma_receive(struct uart_dev_s *dev)
432	{
433	    struct sifli_uart *uart = (struct sifli_uart *)dev->priv;
434	    IRQn_Type irq;
435	
436	    //_info("Start uart DMA\n");
437	
438	    /* Check if DMA is properly configured */
439	    if (!uart->uart_rx_dma_flag)
440	    {
441	        return OK;
442	    }
443	
444	    if (uart->config->dma_rx == NULL || uart->config->dma_rx->Instance == NULL)
445	    {
446	        return -EINVAL;
447	    }
448	
449	    __HAL_LINKDMA(&(uart->handle), hdmarx, uart->dma_rx.handle);
450	    uart->handle.hdmarx->Instance = uart->config->dma_rx->Instance;
451	    uart->handle.hdmarx->Init.Request = uart->config->dma_rx->request;
452	    uart->handle.hdmarx->Init.Direction = DMA_PERIPH_TO_MEMORY;
453	    uart->handle.hdmarx->Init.PeriphInc = DMA_PINC_DISABLE;
454	    uart->handle.hdmarx->Init.MemInc = DMA_MINC_ENABLE;
455	    uart->handle.hdmarx->Init.PeriphDataAlignment = DMA_PDATAALIGN_BYTE;
456	    uart->handle.hdmarx->Init.MemDataAlignment = DMA_MDATAALIGN_BYTE;
457	    uart->handle.hdmarx->Init.Mode = DMA_CIRCULAR;
458	    uart->handle.hdmarx->Init.Priority = DMA_PRIORITY_HIGH;
459	    irq = uart->config->dma_rx->dma_irq;
460	
461	    /* Initialize the DMA with circular mode */
462	    HAL_DMA_Init(uart->handle.hdmarx);
463	
464	    /* Reset last_index for DMA circular buffer tracking */
465	    uart->dma_rx.last_index = 0;
466	
467	    up_invalidate_dcache((uintptr_t)uart->serial.recv.buffer,
468	                         (uintptr_t)uart->serial.recv.buffer +
469	                         uart->serial.recv.size);
470	
471	    /* Clear any pending DMA interrupts before starting */
472	    HAL_UART_Receive_DMA(&(uart->handle), (uint8_t*)uart->serial.recv.buffer, uart->serial.recv.size);
473	    /* Note: IRQ will be enabled in sifli_attach() after irq_attach() */
474	    __HAL_UART_ENABLE_IT(&(uart->handle), UART_IT_IDLE);    
475	    return 0;
476	}
