571	/****************************************************************************
572	 * Name: nrf53_attach
573	 *
574	 * Description:
575	 *   Configure the UART to operation in interrupt driven mode.  This method
576	 *   is called when the serial port is opened.  Normally, this is just after
577	 *   the the setup() method is called, however, the serial console may
578	 *   operate in a non-interrupt driven mode during the boot phase.
579	 *
580	 *   RX and TX interrupts are not enabled when by the attach method (unless
581	 *   the hardware supports multiple levels of interrupt enabling).
582	 *   The RX and TX interrupts are not enabled until the txint() and rxint()
583	 *   methods are called.
584	 *
585	 ****************************************************************************/
586	
587	static int sifli_attach(struct uart_dev_s *dev)
588	{
589	    struct sifli_uart *uart = (struct sifli_uart *)dev->priv;
590	    int ret;
591	
592	    /* sifli_attach called */
593	    
594	    //_info("recv %p\n", &(dev->recv));
595	    // Start to receive data.
596	    sifli_dma_receive(dev);
597	
598	    /* Attach and enable the IRQ(s).  The interrupts are (probably) still
599	    * disabled in the C2 register.
600	    */
601	    ret = irq_attach(uart->config->irq_type+16, uart_isr, uart);
602	    if (ret == OK) {
603	        up_enable_irq(uart->config->irq_type+16);
604	    }
605	
606	    if (uart->config->dma_rx && uart->config->dma_rx->dma_irq) {
607	        ret=irq_attach(uart->config->dma_rx->dma_irq+16, uart_dma_isr, uart);
608	        if (ret == OK) {
609	            up_enable_irq(uart->config->dma_rx->dma_irq+16);
610	        }
611	    }
612	    return ret;
613	}
614	
615	/****************************************************************************
616	 * Name: nrf53_detach
617	 *
618	 * Description:
619	 *   Detach UART interrupts.  This method is called when the serial port is
620	 *   closed normally just before the shutdown method is called.
621	 *   The exception is the serial console which is never shutdown.
622	 *
623	 ****************************************************************************/
624	
625	static void sifli_detach(struct uart_dev_s *dev)
626	{
627	    struct sifli_uart *uart = (struct sifli_uart *)dev->priv;
628	
629	    /* Disable interrupts */
630	    up_disable_irq(uart->config->irq_type+16);
631	
632	    /* Detach from the interrupt(s) */
633	    irq_detach(uart->config->irq_type+16);
634	
635	    if (uart->config->dma_rx && uart->config->dma_rx->dma_irq) {
636	        /* Disable interrupts */
637	        up_disable_irq(uart->config->dma_rx->dma_irq+16);
638	        
639	        /* Detach from the interrupt(s) */
640	        irq_detach(uart->config->dma_rx->dma_irq+16);
641	
642	        
643	    }
644	}
645	
646	
647	/****************************************************************************
648	 * Name: sifli_shutdown
649	 *
650	 * Description:
651	 *   Disable the UART.  This method is called when the serial
652	 *   port is closed
653	 *
654	 ****************************************************************************/
655	
656	static void sifli_shutdown(struct uart_dev_s *dev)
657	{
658	    struct sifli_uart *uart = (struct sifli_uart *)dev->priv;
659	
660	    /* Disable interrupts */
661	    HAL_UART_DeInit(&uart->handle);
662	}
