685	static void sifli_serial_pm_setsuspend(bool suspend)
686	{
687	  int n;
688	  int obj_num = sizeof(uart_obj) / sizeof(uart_obj[0]);
689	
690	  /* Already in desired state? */
691	
692	  if (suspend == g_serialpm.serial_suspended)
693	    return;
694	
695	  g_serialpm.serial_suspended = suspend;
696	
697	
698	  if (!suspend)
699	  {
700	    for (n = 0; n < obj_num; n++)    
701	    {
702	        sifli_setup(&uart_obj[n].serial);
703	        sifli_attach(&uart_obj[n].serial);
704	    }
705	  }
706	}
