709	                                   enum pm_state_e pmstate)
710	{
711	  switch (pmstate)
712	    {
713	      case PM_NORMAL:
714	        {
715	          sifli_serial_pm_setsuspend(false);
716	        }
717	        break;
718	
719	      case PM_IDLE:
720	        {
721	          sifli_serial_pm_setsuspend(false);
722	        }
723	        break;
724	
725	      case PM_STANDBY:
726	        {
727	          sifli_serial_pm_setsuspend(true);
728	        }
729	        break;
730	
731	      case PM_SLEEP:
732	        {
733	          sifli_serial_pm_setsuspend(true);
734	        }
735	        break;
736	
737	      default:
738	
739	        /* Should not get here */
740	
741	        break;
742	    }
743	}
