747	/**
748	 * Uart common interrupt process. This need add to uart ISR.
749	 *
750	 * @param serial serial device
751	 */
752	int uart_isr(int irq, FAR void *context, FAR void *arg)
753	{
754	    struct sifli_uart *uart;
755	
756	
757	    uart = (struct sifli_uart *) arg;
758	
759	    /* Clear error flags first to prevent data loss */
760	    if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_ORE) != RESET)
761	    {
762	        __HAL_UART_CLEAR_OREFLAG(&uart->handle);
763	    }
764	    if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_NE) != RESET)
765	    {
766	        __HAL_UART_CLEAR_NEFLAG(&uart->handle);
767	    }
768	    if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_FE) != RESET)
769	    {
770	        __HAL_UART_CLEAR_FEFLAG(&uart->handle);
771	    }
772	    if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_PE) != RESET)
773	    {
774	        __HAL_UART_CLEAR_PEFLAG(&uart->handle);
775	    }
776	
777	    /* UART in mode Receiver -------------------------------------------------*/
778	    if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_RXNE) != RESET)
779	    {
780	        uart_recvchars(&(uart->serial));
781	    }
782	
783	    /* DMA RX IDLE interrupt */
784	    if ((uart->uart_rx_dma_flag) && (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_IDLE) != RESET))
785	    {
786	        HAL_UART_RxCpltCallback(&(uart->handle));
787	        __HAL_UART_CLEAR_IDLEFLAG(&uart->handle);
788	    }
789	
790	    /* DMA TX complete interrupt */
791	    if ((uart->uart_tx_dma_flag) && (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_TC) != RESET))
792	    {
793	        __HAL_UART_CLEAR_FLAG(&uart->handle, UART_CLEAR_TCF);
794	        uart->handle.gState = HAL_UART_STATE_READY;
795	        uart_xmitchars(&uart->serial);
796	    }
797	
798	    /* Clear remaining flags */
799	    if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_CTS) != RESET)
800	    {
801	        UART_INSTANCE_CLEAR_FUNCTION(&(uart->handle), UART_FLAG_CTS);
802	    }
803	    if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_TXE) != RESET)
804	    {
805	        UART_INSTANCE_CLEAR_FUNCTION(&(uart->handle), UART_FLAG_TXE);
806	    }
807	
808	    return OK;
809	}
