824	/**
825	  * @brief  Rx Half Transfer completed callback.
826	  * @param huart UART handle.
827	  * @retval None
828	  */
829	void HAL_UART_RxHalfCpltCallback(UART_HandleTypeDef *huart)
830	{
831	    struct sifli_uart *uart;
832	    int recv_total_index;
833	
834	    uart = (struct sifli_uart *)huart;
835	
836	    /* Get current DMA write position */
837	    recv_total_index = uart->serial.recv.size - __HAL_DMA_GET_COUNTER(&uart->dma_rx.handle);
838	
839	    up_invalidate_dcache((uintptr_t)uart->serial.recv.buffer,
840	                         (uintptr_t)uart->serial.recv.buffer +
841	                         uart->serial.recv.size);
