109	/****************************************************************************
110	 * Public Functions
111	 ****************************************************************************/
112	
113	/****************************************************************************
114	 * Name: board_boot_image
115	 *
116	 * Description:
117	 *   Called by nxboot (via BOARDIOC_BOOT_IMAGE) to load the application
118	 *   image from NAND flash into PSRAM and jump to it.
119	 *
120	 *   IMPORTANT: PSRAM is NOT re-initialized here.  The PSRAM controller
121	 *   was set up during early boot (HAL_PreInit → bsp_psramc_init).
122	 *   Re-initializing PSRAM would destroy the application code and data
123	 *   that we copy from NAND.
124	 *
125	 * Input Parameters:
126	 *   path     - Path to the NAND MTD partition (e.g. "/dev/ota0")
127	 *   hdr_size - Size of the nxboot image header (CONFIG_NXBOOT_HEADER_SIZE)
128	 *
129	 ****************************************************************************/
130	
131	int board_boot_image(const char *path, uint32_t hdr_size)
132	{
133	  static struct arm_vector_table vt;
134	  struct file file;
135	  ssize_t bytes;
136	  uint32_t image_size;
137	  uint32_t remaining;
138	  uint32_t chunk;
139	  uint32_t dest;
140	  off_t src_off;
141	  int ret;
142	  uint8_t buf[SF32LB58_COPY_BUF_SIZE];
143	
144	  syslog(LOG_INFO, "board_boot_image: loading %s (hdr_size=0x%lx)\n",
145	         path, (unsigned long)hdr_size);
146	
147	  ret = file_open(&file, path, O_RDONLY | O_CLOEXEC);
148	  if (ret < 0)
149	    {
150	      syslog(LOG_ERR, "Failed to open %s: %d\n", path, ret);
151	      return ret;
152	    }
153	
154	  /* Read the image size from the header (offset 4, uint32_t) */
155	
156	  bytes = file_pread(&file, &image_size, sizeof(image_size), 4);
157	  if (bytes != sizeof(image_size))
158	    {
159	      syslog(LOG_ERR, "Failed to read image size: %ld\n", (long)bytes);
160	      file_close(&file);
161	      return bytes < 0 ? (int)bytes : -1;
162	    }
163	
164	  if (image_size == 0 || image_size > SF32LB58_APP_MAX_IMAGE_SIZE)
165	    {
166	      syslog(LOG_ERR, "Invalid image size: 0x%08lx\n",
167	             (unsigned long)image_size);
168	      file_close(&file);
169	      return -EINVAL;
170	    }
171	
172	  syslog(LOG_INFO, "board_boot_image: image_size=0x%08lx, copying to "
173	         "PSRAM @ 0x%08lx\n",
174	         (unsigned long)image_size,
175	         (unsigned long)SF32LB58_APP_PSRAM_LOAD_ADDR);
176	
177	  /* Read the ARM vector table (SP + reset handler) from after the header */
178	
179	  bytes = file_pread(&file, &vt, sizeof(vt), hdr_size);
180	  if (bytes != sizeof(vt))
181	    {
182	      syslog(LOG_ERR, "Failed to read vector table: %ld\n", (long)bytes);
183	      file_close(&file);
184	      return bytes < 0 ? (int)bytes : -1;
185	    }
186	
187	  syslog(LOG_INFO, "board_boot_image: VT sp=0x%08lx reset=0x%08lx\n",
188	         (unsigned long)vt.spr, (unsigned long)vt.reset);
189	
190	  /* Copy the entire image from NAND to PSRAM.
191	   * We read from the NAND partition starting at hdr_size (after header)
192	   * and write to PSRAM at the load address.
193	   *
194	   * NOTE: We cannot use file_pread directly into PSRAM because the
195	   * NAND MTD driver uses its own page buffers.  We read into a SRAM
196	   * buffer and memcpy to PSRAM.
197	   */
198	
199	  src_off = (off_t)hdr_size;
200	  dest = SF32LB58_APP_PSRAM_LOAD_ADDR;
201	  remaining = image_size;
202	
203	  while (remaining > 0)
204	    {
205	      chunk = remaining > SF32LB58_COPY_BUF_SIZE ?
206	              SF32LB58_COPY_BUF_SIZE : remaining;
207	
208	      bytes = file_pread(&file, buf, chunk, src_off);
209	      if (bytes != (ssize_t)chunk)
210	        {
211	          syslog(LOG_ERR,
212	                 "Failed to read image at offset 0x%08lx: %ld\n",
213	                 (unsigned long)src_off, (long)bytes);
214	          file_close(&file);
215	          return bytes < 0 ? (int)bytes : -1;
216	        }
217	
218	      memcpy((void *)(uintptr_t)dest, buf, chunk);
219	
220	      src_off += chunk;
221	      dest += chunk;
222	      remaining -= chunk;
223	    }
224	
225	  file_close(&file);
226	
227	  syslog(LOG_INFO,
228	         "board_boot_image: copy complete, jumping to PSRAM...\n");
229	
230	  /* *** DO NOT re-initialize PSRAM here ***
231	   * The application's .text, .data, and .bss sections are now in PSRAM.
232	   * Any PSRAM controller re-initialization would destroy them.
233	   */
234	
235	  systick_disable();
236	  cleanup_arm_nvic();
237	
238	#ifdef CONFIG_ARMV8M_DCACHE
239	  up_disable_dcache();
240	#endif
241	#ifdef CONFIG_ARMV8M_ICACHE
242	  up_disable_icache();
243	#endif
244	
245	#ifdef CONFIG_ARM_MPU
246	  mpu_control(false, false, false);
247	#endif
248	
249	  /* Set main and process stack pointers, jump to reset handler.
250	   * Use the vector table we read from the image (which points to
251	   * addresses relative to the PSRAM load address).
252	   */
253	
254	  __asm__ __volatile__("\tmsr msp, %0\n"
255	                       "\tmsr control, %1\n"
256	                       "\tisb\n"
257	                       "\tmov pc, %2\n"
258	                       :
259	                       : "r" (vt.spr), "r" (0), "r" (vt.reset));
260	
261	  /* Should never reach here */
262	
263	  return 0;
264	}
265

