extern void arm_earlyserialinit(void);

#ifdef CONFIG_BOARD_EARLY_INITIALIZE
void board_early_initialize(void)
{
  /* Initialize UART1 for serial console.
   * This must be called before arm_serialinit() (which registers /dev/console).
   * At this point, clocks and power domains are already configured by
   * BSP_Board_PreInit() during HAL_Init().
   */
  arm_earlyserialinit();
}
#endif

