#ifdef CONFIG_BOARD_EARLY_INITIALIZE
void board_early_initialize(void)
{
  /* Nothing extra needed — HAL_PreInit() handles clocks, PSRAM, pinmux */
}
#endif

input.old_string:
  __cmsis_copy();

  arm_earlyserialinit();
  while(1) {
    arm_lowputc('A'); /* data segment init done */
  }    

#ifdef CONFIG_ARMV8M_ICACHE
  up_enable_icache();
#endif

#ifdef CONFIG_ARMV8M_DCACHE
  up_enable_dcache();
#endif
    arm_lowputc('B'); /* cache enable done */

  /* Call HAL_Init() with interrupts disabled.
   * Some HAL functions may trigger hardware events that could
   * generate interrupts, but they won't fire while interrupts are disabled.
   */
    HAL_Init();
    arm_lowputc('C'); /* HAL init done */

input.new_string:
  __cmsis_copy();

  arm_lowputc('A'); /* data segment init done — uses ROM-bootloader UART config */

#ifdef CONFIG_ARMV8M_ICACHE
  up_enable_icache();
#endif

#ifdef CONFIG_ARMV8M_DCACHE
  up_enable_dcache();
#endif
    arm_lowputc('B'); /* cache enable done */

  /* Call HAL_Init() first — it calls BSP_Board_PreInit() which configures
   * system clocks (DLL1@240MHz), peripheral clocks (USART1), and flash/PSRAM.
   * Must happen before any HAL peripheral init (including UART).
   */
    HAL_Init();

  /* Now that clocks are configured, initialize UART1 properly.
   * arm_lowputc('A') and 'B' above used the ROM bootloader's UART config.
   * After BSP_Board_PreInit() reconfigured clocks, the baud rate divisor
   * is wrong. Re-initialize UART1 with the correct baud rate for the new clock.
   */
    arm_earlyserialinit();

    arm_lowputc('C'); /* HAL init + UART done */
